import mongoose from 'mongoose';
import { PRODUCT_STATUS } from '../constants/index.js';
import { jsonOptions } from './shared/json.js';
import { softDelete } from './shared/softDelete.js';

const { ObjectId } = mongoose.Schema.Types;

// Something that is sold: a physical product or a service.
const productSchema = new mongoose.Schema(
  {
    // Generated by the server, or supplied and validated. Unique for ever - a
    // deleted product's SKU is not reused - and fixed once the product exists.
    sku: { type: String, required: true, unique: true, immutable: true, uppercase: true, trim: true, maxlength: 40 },
    name: { type: String, required: true, trim: true, maxlength: 200, index: true },
    description: { type: String, trim: true, maxlength: 5000 },
    categoryId: { type: ObjectId, ref: 'ProductCategory', index: true },
    unitId: { type: ObjectId, ref: 'Unit' },
    // Selling price before tax, and what it costs us. One implied currency.
    basePrice: { type: Number, required: true, min: 0, index: true },
    costPrice: { type: Number, min: 0 },
    taxId: { type: ObjectId, ref: 'Tax' },
    status: {
      type: String,
      enum: Object.values(PRODUCT_STATUS),
      default: PRODUCT_STATUS.ACTIVE,
      index: true,
    },
    image: { type: String, trim: true, maxlength: 2048 },
    organizationId: { type: ObjectId, ref: 'Organization', index: true },
    createdBy: { type: ObjectId, ref: 'User' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        categoryId: 'category',
        unitId: 'unit',
        taxId: 'tax',
        organizationId: 'organization',
        createdBy: 'createdByUser',
      },
    }),
  }
);

softDelete(productSchema);

export default mongoose.model('Product', productSchema);
